sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // --- Collect CI classes ---
    var ci_classes = [];
    if (request.queryParams.ci_classes) {
        ci_classes = request.queryParams.ci_classes[0].split(",");
    }

    var ci_classes_parm = request.queryParams.sysparm_ci_classes;
    var ciClassesArr = [];
    if (ci_classes_parm) {
        ciClassesArr = ci_classes_parm.split(",");
    }

    // Merge both query params (unique values only)
    var allCiClasses = ci_classes.concat(ciClassesArr)
        .filter(function(item, pos, arr) { return arr.indexOf(item) === pos; });

    var metrics = { };

    // --- Validate each CI class ---
    var invalidClasses = [];
    var validCiClasses = [];

    allCiClasses.forEach(function(ciClass) {
		ciClass = ciClass.trim();
        var gr = new GlideRecord('sys_db_object');
        gr.addQuery('name', ciClass);
		gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            validCiClasses.push(ciClass);
        } else {
            invalidClasses.push(ciClass);
        }
    });

    // If any invalid CI classes found → return error
    if (invalidClasses.length > 0) {
        response.setStatus(400); // Bad Request
        return {
            error: "Invalid CI class table name(s)",
            invalid: invalidClasses
        };
    }

    // --- Static patterns ---
    var urlPatterns = [
        'api/now/table/cmdb_categories',
        'api/now/table/cmdb_ci',
        'api/now/table/cmdb_rel_ci',
        'api/now/table/cmdb_rel_type'
    ];

    // --- Add one pattern per valid CI class ---
    validCiClasses.forEach(function(ciClass) {
        urlPatterns.push('api/now/table/' + ciClass);
    });

    // --- Process all patterns ---
    urlPatterns.forEach(function(pattern) {
        var count = 0;
        var totalResponseTime = 0;
        var totalSqlTime = 0;
        var totalCPUTime = 0;
        var cpu_usage = 0;
        var network_time = 0;

        var logGr = new GlideRecord('syslog_transaction');
        logGr.addQuery('type', 'rest');
        logGr.addQuery('url', 'CONTAINS', pattern);
        logGr.query();

        while (logGr.next()) {
            count++;
            network_time += parseInt(logGr.getValue('network_time')) || 0;
            totalResponseTime += parseInt(logGr.getValue('response_time')) || 0;
            totalSqlTime += parseInt(logGr.getValue('sql_time')) || 0;
            totalCPUTime += parseInt(logGr.getValue('cpu_time')) || 0;
            cpu_usage += parseInt(logGr.getValue('cpu_usage')) || 0;
        }

        metrics[pattern] = {
            call_count: count,
            network_time: count > 0 ? (network_time / count) + " ms" : "0 ms",
            avg_response_time: count > 0 ? (totalResponseTime / count) + " ms" : "0 ms",
            avg_sql_time: count > 0 ? (totalSqlTime / count) + " ms" : "0 ms",
            avg_cpu_time: count > 0 ? (totalCPUTime / count) + " ms" : "0 ms",
            cpu_usage: count > 0 ? (cpu_usage / count) : 0
        };
    });

    return metrics;

})(request, response);
